import { test, expect } from "@playwright/test";
import { readFileSync } from "node:fs";

// An integration runner can supply a bundle generated by the real Python collector
// against mocked GitHub HTTP responses, then exercise that output in the browser.
const bundle = process.env.COLLECTION_BUNDLE;
test.beforeEach(async ({ page }) => {
  for (const name of ["projects", "profile"]) {
    const filename = bundle
      ? `${bundle}/data/${name}.json`
      : new URL(`./fixtures/${name}.json`, import.meta.url);
    await page.route(`**/data/${name}.json`, (route) =>
      route.fulfill({
        contentType: "application/json",
        body: readFileSync(filename, "utf8"),
      }),
    );
  }
});

test("photo-first hero and projects work under a Pages subpath", async ({
  page,
}) => {
  const errors: string[] = [];
  page.on("pageerror", (error) => errors.push(error.message));
  await page.goto("./");
  await expect(
    page.getByRole("heading", { name: /Arya Girigoudar/ }),
  ).toBeVisible();
  const photo = page.getByRole("img", {
    name: "Arya outdoors, wearing sunglasses",
  });
  await expect(photo).toBeVisible();
  expect(
    await photo.evaluate((image: HTMLImageElement) => image.naturalWidth),
  ).toBeGreaterThan(0);
  await expect(page.locator(".project-card").first()).toBeVisible();
  expect(
    await page
      .locator("body")
      .evaluate((el) => el.scrollWidth <= window.innerWidth),
  ).toBeTruthy();
  expect(errors).toEqual([]);
});

test("shy reaction opens only on request, pauses, and restores focus", async ({
  page,
}) => {
  const gifs: string[] = [];
  page.on("request", (request) => {
    if (request.url().endsWith(".gif")) gifs.push(request.url());
  });
  await page.goto("./");
  await expect(
    page.getByRole("button", { name: "I’d hire you" }),
  ).toBeVisible();
  expect(gifs).toEqual([]);
  await page.getByRole("button", { name: "I’d hire you" }).click();
  const dialog = page.getByRole("dialog");
  await expect(dialog).toBeVisible();
  await expect(dialog.getByRole("img")).toHaveAttribute(
    "src",
    "/portfolio/media/shy.gif",
  );
  await dialog.getByRole("button", { name: "Pause animation" }).click();
  await expect(dialog.getByRole("img")).toHaveAttribute(
    "src",
    "/portfolio/media/shy.png",
  );
  await expect(
    dialog.getByRole("link", { name: "Let’s talk" }),
  ).toHaveAttribute("href", /^mailto:/);
  await page.keyboard.press("Escape");
  await expect(dialog).not.toBeVisible();
  await expect(
    page.getByRole("button", { name: "I’d hire you" }),
  ).toBeFocused();
});

test("reduced motion uses a still reaction by default", async ({ page }) => {
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("./");
  await page.getByRole("button", { name: "You’re a good fit" }).click();
  await expect(page.getByRole("dialog").getByRole("img")).toHaveAttribute(
    "src",
    "/portfolio/media/shy.png",
  );
});

test("search, empty results and reset", async ({ page }) => {
  await page.goto("./");
  await expect(page.locator(".project-card").first()).toBeVisible();
  await page.getByRole("searchbox").fill("thisprojectdoesnotexist");
  await expect(page.locator(".project-card")).toHaveCount(0);
  await expect(
    page.getByText("No matches. Even my projects have boundaries."),
  ).toBeVisible();
  await page.getByRole("button", { name: "Clear filters" }).click();
  await expect(page.locator(".project-card").first()).toBeVisible();
});

test("filter by technology and expand details", async ({ page }) => {
  await page.goto("./");
  await expect(page.locator(".project-card").first()).toBeVisible();
  const select = page.getByRole("combobox", { name: "Technology" });
  const value =
    (await select.locator("option").nth(1).getAttribute("value")) ??
    (await select.locator("option").nth(1).textContent());
  await select.selectOption(value!);
  const card = page.locator(".project-card").first();
  await expect(card).toBeVisible();
  await card.locator("summary").click();
  await expect(card.locator("details")).toHaveAttribute("open", "");
  await expect(card.getByRole("link", { name: /^Source/ })).toHaveCount(0);
});

if (!bundle) {
  test("empty dataset is a useful state", async ({ page }) => {
    await page.route("**/data/projects.json", (route) =>
      route.fulfill({
        json: {
          schema_version: 1,
          generated_at: "2026-11-02T00:00:00Z",
          projects: [],
        },
      }),
    );
    await page.goto("./");
    await expect(
      page.getByText("Nothing public yet. The plot is still developing."),
    ).toBeVisible();
  });

  test("failed request shows saved valid dataset", async ({ page }) => {
    await page.goto("./");
    await expect(page.locator(".project-card").first()).toBeVisible();
    await page.route("**/data/projects.json", (route) => route.abort());
    await page.reload();
    await expect(
      page.getByText(/Showing the last saved collection/),
    ).toBeVisible();
    await expect(page.locator(".project-card").first()).toBeVisible();
  });

  test("failed first request has a readable error", async ({ page }) => {
    await page.route("**/data/projects.json", (route) => route.abort());
    await page.goto("./");
    await expect(page.getByRole("alert")).toContainText(
      "The projects have chosen mystery",
    );
  });

  test("invalid data is rejected", async ({ page }) => {
    await page.route("**/data/projects.json", (route) =>
      route.fulfill({ json: { projects: [{ title: "<script>" }] } }),
    );
    await page.goto("./");
    await expect(page.getByRole("alert")).toBeVisible();
    await expect(page.locator(".project-card")).toHaveCount(0);
  });
}

test("resume is a downloadable PDF", async ({ page, request }) => {
  await page.goto("./");
  const resume = page.locator(".hero-resume");
  await expect(resume).toHaveAttribute("download", "");
  const response = await request.get("./resume/resume.pdf");
  expect(response.ok()).toBeTruthy();
  expect((await response.body()).subarray(0, 5).toString()).toBe("%PDF-");
});

test("page has no automated accessibility violations", async ({ page }) => {
  const { default: AxeBuilder } = await import("@axe-core/playwright");
  await page.goto("./");
  await expect(page.locator(".project-card").first()).toBeVisible();
  const results = await new AxeBuilder({ page })
    .withTags(["wcag2a", "wcag2aa", "wcag21aa"])
    .analyze();
  expect(results.violations).toEqual([]);
});

if (bundle) {
  test("private GitHub metadata reaches the browser without repository identity", async ({
    page,
  }) => {
    await page.goto("./");
    await expect(
      page.getByRole("heading", { name: "Collected through the GitHub API" }),
    ).toBeVisible();
    expect(await page.locator("body").innerText()).not.toContain(
      "do-not-disclose",
    );
  });
}
